   <main>
     <section class="preference-card" aria-labelledby="page-title">
       <div class="card-header">
         <p class="eyebrow">Preferences</p>
         <h1 id="page-title">Stay in the loop</h1>
         <p class="intro">Choose how you would like product updates, reminders, and important account messages delivered.</p>
       </div>

       <form id="notification-form">
         <fieldset class="form-field">
           <legend>How do you prefer to receive notifications?</legend>

           <div class="radio-group">
             <label class="radio-option">
               <input type="radio" name="notificationPreference" value="Email" required>
               <span>Email</span>
             </label>

             <label class="radio-option">
               <input type="radio" name="notificationPreference" value="SMS">
               <span>SMS</span>
             </label>

             <label class="radio-option">
               <input type="radio" name="notificationPreference" value="Push Notifications">
               <span>Push Notifications</span>
             </label>
           </div>
         </fieldset>

         <button type="submit">Save preference</button>
         <p class="status" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#notification-form");
     const status = document.querySelector("#form-status");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const formData = new FormData(form);
       const preference = formData.get("notificationPreference");

       status.textContent = `Preference saved: ${preference}`;
       status.classList.add("success");
     });
   </script>
 </body>
